#!/usr/bin/env python3
from pathlib import Path
import os
import re
import sys

app_gradle = Path("android/app/build.gradle")
if not app_gradle.is_file():
    print("ERROR: android/app/build.gradle was not generated by Capacitor.", file=sys.stderr)
    raise SystemExit(1)

version_name = os.environ.get("VERSION_NAME", "").strip()
version_code = os.environ.get("VERSION_CODE", "").strip()

if not version_name or not version_code:
    print("ERROR: VERSION_NAME and VERSION_CODE are required.", file=sys.stderr)
    raise SystemExit(1)

text = app_gradle.read_text(encoding="utf-8")

text, namespace_count = re.subn(
    r'(?m)^\s*namespace\s*=\s*"[^"]+"',
    '    namespace = "com.sevenx.anime"',
    text,
    count=1,
)
if namespace_count != 1:
    print("ERROR: could not locate the generated Android namespace.", file=sys.stderr)
    raise SystemExit(1)

text, app_id_count = re.subn(
    r'(?m)^\s*applicationId\s+"[^"]+"',
    '        applicationId "com.sevenx.anime"',
    text,
    count=1,
)
if app_id_count != 1:
    print("ERROR: could not locate the generated Android applicationId.", file=sys.stderr)
    raise SystemExit(1)

text, code_count = re.subn(
    r'(?m)^\s*versionCode\s+\d+',
    f'        versionCode {version_code}',
    text,
    count=1,
)
if code_count != 1:
    print("ERROR: could not locate the generated Android versionCode.", file=sys.stderr)
    raise SystemExit(1)

text, name_count = re.subn(
    r'(?m)^\s*versionName\s+"[^"]+"',
    f'        versionName "{version_name}"',
    text,
    count=1,
)
if name_count != 1:
    print("ERROR: could not locate the generated Android versionName.", file=sys.stderr)
    raise SystemExit(1)

if 'applicationIdSuffix ".debug"' not in text:
    marker = "    buildTypes {"
    debug_block = """    buildTypes {
        debug {
            applicationIdSuffix ".debug"
            debuggable true
        }
"""
    if marker not in text:
        print("ERROR: could not locate Android buildTypes block.", file=sys.stderr)
        raise SystemExit(1)
    text = text.replace(marker, debug_block, 1)

app_id_match = re.search(r'applicationId\s+"([^"]+)"', text)
namespace_match = re.search(r'namespace\s*=\s*"([^"]+)"', text)
if not app_id_match or app_id_match.group(1) != "com.sevenx.anime":
    print("ERROR: production applicationId was not configured as expected.", file=sys.stderr)
    raise SystemExit(1)
if not namespace_match or namespace_match.group(1) != "com.sevenx.anime":
    print("ERROR: Android namespace was not configured as expected.", file=sys.stderr)
    raise SystemExit(1)

# AGP 9 rejects the legacy ProGuard default from the Capacitor app template.
legacy_proguard_files = (
    "getDefaultProguardFile('proguard-android.txt')",
    'getDefaultProguardFile("proguard-android.txt")',
)
proguard_replacements = sum(text.count(item) for item in legacy_proguard_files)
for old_proguard in legacy_proguard_files:
    text = text.replace(
        old_proguard,
        old_proguard.replace("proguard-android.txt", "proguard-android-optimize.txt"),
    )
if proguard_replacements == 0 and "proguard-android-optimize.txt" not in text:
    print("ERROR: could not update the generated ProGuard defaults for AGP 9.", file=sys.stderr)
    raise SystemExit(1)

app_gradle.write_text(text, encoding="utf-8")

# Capacitor plugins contain their own Android library build files under node_modules.
# AGP 9 rejects the legacy ProGuard default in those files as well as in :app.
capacitor_plugin_root = Path("node_modules/@capacitor")
if capacitor_plugin_root.is_dir():
    plugin_gradle_files = list(capacitor_plugin_root.rglob("*.gradle"))
    for plugin_gradle in plugin_gradle_files:
        plugin_text = plugin_gradle.read_text(encoding="utf-8")
        updated_plugin_text = plugin_text.replace(
            "getDefaultProguardFile('proguard-android.txt')",
            "getDefaultProguardFile('proguard-android-optimize.txt')",
        ).replace(
            'getDefaultProguardFile("proguard-android.txt")',
            'getDefaultProguardFile("proguard-android-optimize.txt")',
        )
        if updated_plugin_text != plugin_text:
            plugin_gradle.write_text(updated_plugin_text, encoding="utf-8")

capacitor_app_gradle = Path("node_modules/@capacitor/app/android/build.gradle")
if capacitor_app_gradle.is_file():
    capacitor_app_text = capacitor_app_gradle.read_text(encoding="utf-8")
    if "getDefaultProguardFile('proguard-android.txt')" in capacitor_app_text or 'getDefaultProguardFile("proguard-android.txt")' in capacitor_app_text:
        print("ERROR: AGP 9 legacy ProGuard default remains in @capacitor/app.", file=sys.stderr)
        raise SystemExit(1)

# The selected adblock-rust AAR declares compileSdk 37. Align the generated
# Capacitor toolchain with the first stable AGP release supporting Android 17.
root_gradle = Path("android/build.gradle")
if not root_gradle.is_file():
    print("ERROR: generated android/build.gradle is missing.", file=sys.stderr)
    raise SystemExit(1)
agp_pattern = r"com\.android\.tools\.build:gradle:[0-9.]+"
agp_files = []
for gradle_file in Path("android").rglob("*.gradle"):
    gradle_text = gradle_file.read_text(encoding="utf-8")
    gradle_text, agp_count = re.subn(
        agp_pattern,
        "com.android.tools.build:gradle:9.1.1",
        gradle_text,
    )
    if agp_count:
        gradle_file.write_text(gradle_text, encoding="utf-8")
        agp_files.append(gradle_file.resolve())
if root_gradle.resolve() not in agp_files:
    print("ERROR: could not update the root Android Gradle Plugin version.", file=sys.stderr)
    raise SystemExit(1)

# Capacitor copies the core Android library into the generated project; keep its
# nested buildscript on the same AGP version to avoid mixed plugin classpaths.
capacitor_gradle = Path("android/capacitor/build.gradle")
if capacitor_gradle.is_file() and "com.android.tools.build:gradle:9.1.1" not in capacitor_gradle.read_text(encoding="utf-8"):
    print("ERROR: Capacitor Android module did not inherit AGP 9.1.1.", file=sys.stderr)
    raise SystemExit(1)

wrapper_properties = Path("android/gradle/wrapper/gradle-wrapper.properties")
if not wrapper_properties.is_file():
    print("ERROR: generated Gradle wrapper properties are missing.", file=sys.stderr)
    raise SystemExit(1)
wrapper_text = wrapper_properties.read_text(encoding="utf-8")
wrapper_text, wrapper_count = re.subn(
    r"(?m)^distributionUrl=.*$",
    lambda _: r"distributionUrl=https\://services.gradle.org/distributions/gradle-9.3.1-bin.zip",
    wrapper_text,
    count=1,
)
if wrapper_count != 1:
    print("ERROR: could not locate the Gradle wrapper distribution URL.", file=sys.stderr)
    raise SystemExit(1)
wrapper_properties.write_text(wrapper_text, encoding="utf-8")

strings = Path("android/app/src/main/res/values/strings.xml")
if strings.is_file():
    source_strings = strings.read_text(encoding="utf-8")
    source_strings, _ = re.subn(
        r'(<string name="app_name">).*?(</string>)',
        r'\g<1>7xAnime\g<2>',
        source_strings,
        count=1,
    )
    source_strings, _ = re.subn(
        r'(<string name="title_activity_main">).*?(</string>)',
        r'\g<1>7xAnime\g<2>',
        source_strings,
        count=1,
    )
    source_strings, _ = re.subn(
        r'(<string name="package_name">).*?(</string>)',
        r'\g<1>com.sevenx.anime\g<2>',
        source_strings,
        count=1,
    )
    source_strings, _ = re.subn(
        r'(<string name="custom_url_scheme">).*?(</string>)',
        r'\g<1>com.sevenx.anime\g<2>',
        source_strings,
        count=1,
    )
    strings.write_text(source_strings, encoding="utf-8")

debug_strings = Path("android/app/src/debug/res/values/strings.xml")
debug_strings.parent.mkdir(parents=True, exist_ok=True)
debug_strings.write_text(
    '''<?xml version="1.0" encoding="utf-8"?>
<resources>
    <string name="app_name">7xAnime Debug</string>
    <string name="title_activity_main">7xAnime Debug</string>
</resources>
''',
    encoding="utf-8",
)


# Match 7xTune's proven no-crop launcher strategy: do not use Android adaptive-icon
# XML for this artwork. That XML treats the complete icon image as a foreground layer and
# applies an OEM-dependent mask/scale to it, which clips the outer 7x mark on some launchers.
# Copy the approved PNG byte-for-byte into mipmap-nodpi and point @mipmap launcher refs at it.
brand_dir = Path("public/brand")
brand_icon = brand_dir / "7xanime-icon.png"
brand_wordmark = brand_dir / "7xanime-wordmark.png"
for source in (brand_icon, brand_wordmark):
    if not source.is_file():
        print(f"ERROR: missing 7x Brand Studio asset: {source}", file=sys.stderr)
        raise SystemExit(1)

resource_root = Path("android/app/src/main/res")
launcher_dir = resource_root / "mipmap-nodpi"
launcher_dir.mkdir(parents=True, exist_ok=True)

# Remove all template-generated adaptive icon definitions so Android cannot prefer them
# over the exact source bitmap on Android 8+.
for existing_xml in resource_root.rglob("ic_launcher*.xml"):
    existing_xml.unlink()

# Remove generated density-specific launcher PNGs. Leaving them in place can cause Android
# to pick an old, resized template icon instead of the no-density source below.
for mipmap_dir in resource_root.glob("mipmap-*"):
    if not mipmap_dir.is_dir() or mipmap_dir == launcher_dir:
        continue
    for generated_icon in mipmap_dir.glob("ic_launcher*.png"):
        generated_icon.unlink()

approved_icon_bytes = brand_icon.read_bytes()
launcher_names = (
    "ic_launcher.png",
    "ic_launcher_round.png",
    "ic_launcher_static.png",
    "ic_launcher_static_round.png",
)
for name in launcher_names:
    output = launcher_dir / name
    output.write_bytes(approved_icon_bytes)
    if output.read_bytes() != approved_icon_bytes:
        print(f"ERROR: launcher bitmap differs from approved source: {output}", file=sys.stderr)
        raise SystemExit(1)

# Render the native launch artwork as a true transparent squircle. Keep the approved
# source image and launcher icons untouched; only the splash-specific copy receives
# an antialiased alpha mask, so the splash no longer shows a hard square edge.
try:
    from PIL import Image
except ImportError:
    print("ERROR: Pillow is required to generate the antialiased squircle splash asset.", file=sys.stderr)
    raise SystemExit(1)

from PIL import ImageDraw

splash_source = Image.open(brand_icon).convert("RGBA")
width, height = splash_source.size
if width != height:
    print("ERROR: the approved splash artwork must be square to form a squircle.", file=sys.stderr)
    raise SystemExit(1)

scale = 4
mask_large = Image.new("L", (width * scale, height * scale), 0)
draw = ImageDraw.Draw(mask_large)
# A 22% corner radius gives the soft, squircle-like silhouette seen across 7x apps.
inset = int(round(min(width, height) * 0.012 * scale))
radius = int(round(min(width, height) * 0.22 * scale))
draw.rounded_rectangle(
    (inset, inset, width * scale - inset - 1, height * scale - inset - 1),
    radius=radius,
    fill=255,
)
mask = mask_large.resize((width, height), getattr(Image.Resampling, "LANCZOS"))
splash_source.putalpha(Image.composite(splash_source.getchannel("A"), Image.new("L", (width, height), 0), mask))

splash_dir = resource_root / "drawable-nodpi"
splash_dir.mkdir(parents=True, exist_ok=True)
splash_output = splash_dir / "splash_squircle.png"
splash_source.save(splash_output, format="PNG", optimize=True)

# Capacitor's generated launch theme references @drawable/splash for both legacy
# window background and Android 12+ launch icon. Point those references to our
# squircle-masked copy, leaving the original source art and launcher icons unchanged.
styles = resource_root / "values" / "styles.xml"
if not styles.is_file():
    print("ERROR: generated Android styles.xml is missing; cannot configure squircle splash.", file=sys.stderr)
    raise SystemExit(1)
styles_text = styles.read_text(encoding="utf-8")
styles_text, splash_refs = re.subn(
    r'(<item\s+name="(?:android:background|windowSplashScreenAnimatedIcon)">)\s*@drawable/splash\s*(</item>)',
    r'\g<1>@drawable/splash_squircle\g<2>',
    styles_text,
)
if splash_refs < 1:
    print("ERROR: could not find the generated @drawable/splash theme reference to replace.", file=sys.stderr)
    raise SystemExit(1)
styles.write_text(styles_text, encoding="utf-8")

print(f"Configured native squircle splash from {brand_icon} ({width}x{height}); original artwork and launcher assets remain unchanged.")

print(f"Configured com.sevenx.anime version {version_name} ({version_code}) with byte-identical no-crop launcher bitmaps.")
